#include <bits/stdc++.h>
using namespace std;

int t1, t2, x1, x2, t0, a, b;

long long temprt(long long y1, long long y2) {
    return (y1 * t1 + y2 * t2) / (y1 + y2);
}

bool can(int y1, int y2) {
    long long c1 = 1LL * (a + b) * (1LL * y1 * t1 + 1LL * y2 * t2);
    long long c2 = 1LL * (y1 + y2) * (1LL * a * t1 + 1LL * b * t2);

    if (c1 < c2) return true;
    if (c1 > c2) return false;
    return y1 + y2 > a + b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> t1 >> t2 >> x1 >> x2 >> t0;

    if (t1 == t2) {
        cout << x1 << ' ' << x2;
        return 0;
    }

    if (t0 == t2) {
        cout << 0 << ' ' << x2;
        return 0;
    }

    a = 0;
    b = x2;

    for (int y1 = 1; y1 <= x1; ++y1) {
        long long y2 = 1LL * y1 * (t0 - t1) / (t2 - t0);

        while (y2 < x2 && temprt(y1, y2) < t0)
            ++y2;

        if (y2 <= x2 && temprt(y1, y2) >= t0 && can(y1, y2)) {
            a = y1;
            b = static_cast<int>(y2);
        }
    }

    cout << a << ' ' << b;
    return 0;
}

