#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long t1, t2, x1, x2, t0;
    cin >> t1 >> t2 >> x1 >> x2 >> t0;

    if (t1 == t2) {
        cout << x1 << ' ' << x2;
        return 0;
    }
    if (t0 == t1) {
        cout << x1 << " 0";
        return 0;
    }
    if (t0 == t2) {
        cout << "0 " << x2;
        return 0;
    }

    long long best1 = 0, best2 = x2;

    auto better = [&](long long y1, long long y2) {
        __int128 candidateHeat = (__int128)y1 * t1 + (__int128)y2 * t2;
        __int128 bestHeat = (__int128)best1 * t1 + (__int128)best2 * t2;
        __int128 lhs = candidateHeat * (best1 + best2);
        __int128 rhs = bestHeat * (y1 + y2);

        return lhs < rhs ||
               (lhs == rhs && y1 + y2 > best1 + best2);
    };

    for (long long y1 = 1; y1 <= x1; ++y1) {
        long long numerator = y1 * (t0 - t1);
        long long denominator = t2 - t0;
        long long y2 = (numerator + denominator - 1) / denominator;

        if (y2 <= x2 && better(y1, y2)) {
            best1 = y1;
            best2 = y2;
        }
    }

    cout << best1 << ' ' << best2;
    return 0;
}

